"""Assembles the SPIR-V shaders of the 2D renderer into code_runtime/source/shaders.inc.

The shaders are tiny, so they are assembled directly instead of requiring a GLSL compiler to build the project. The
equivalent GLSL is given next to each shader.

Usage: generate_shaders.py <output.inc>
"""
import struct
import sys

# Opcodes
OP = dict(
    Name=5, MemoryModel=14, EntryPoint=15, ExecutionMode=16, Capability=17,
    TypeVoid=19, TypeInt=21, TypeFloat=22, TypeVector=23, TypeImage=25, TypeSampledImage=27, TypeStruct=30,
    TypePointer=32, TypeFunction=33, Constant=43, ConstantComposite=44, Function=54, FunctionEnd=56, Variable=59,
    Load=61, Store=62, AccessChain=65, Decorate=71, MemberDecorate=72, CompositeConstruct=80, CompositeExtract=81,
    ImageSampleImplicitLod=87, FSub=131, FMul=133, Label=248, Return=253,
)
STORAGE = dict(UniformConstant=0, Input=1, Output=3, PushConstant=9)
DECORATION = dict(Block=2, BuiltIn=11, Location=30, Binding=33, DescriptorSet=34, Offset=35)


def string_words(text):
    data = text.encode("utf-8") + b"\0"
    data += b"\0" * (-len(data) % 4)
    return list(struct.unpack("<%dI" % (len(data) // 4), data))


def float_bits(value):
    return struct.unpack("<I", struct.pack("<f", value))[0]


class Module:
    def __init__(self):
        self.next_id = 1
        self.header = []   # Capabilities, memory model, entry points, execution modes
        self.names = []
        self.annotations = []
        self.types = []    # Types, constants and global variables
        self.code = []

    def id(self):
        i = self.next_id
        self.next_id += 1
        return i

    @staticmethod
    def inst(op, *operands):
        words = []
        for operand in operands:
            if isinstance(operand, list):
                words.extend(operand)
            else:
                words.append(operand)
        return [((len(words) + 1) << 16) | OP[op]] + words

    def assemble(self):
        words = [0x07230203, 0x00010000, 0, self.next_id, 0]
        for part in (self.header, self.names, self.annotations, self.types, self.code):
            for inst in part:
                words.extend(inst)
        return words


def vertex_shader():
    """
    #version 450
    layout(location = 0) in vec2 inPosition;
    layout(location = 1) in vec2 inUV;
    layout(location = 2) in vec4 inColor;
    layout(push_constant) uniform Constants { vec2 scale; } pc; // 1 / size of the target in pixels
    layout(location = 0) out vec2 outUV;
    layout(location = 1) out vec4 outColor;
    void main() {
        vec2 p = inPosition * pc.scale * 2.0 - 1.0;
        gl_Position = vec4(p.x, p.y, 0.0, 1.0);
        gl_PointSize = 1.0;
        outUV = inUV;
        outColor = inColor;
    }
    """
    m = Module()
    i = m.inst
    void, fn, flt, vec2, vec4, int_ = m.id(), m.id(), m.id(), m.id(), m.id(), m.id()
    pv_struct, pc_struct = m.id(), m.id()
    p_in_v2, p_in_v4, p_out_v2, p_out_v4, p_out_pv, p_pc, p_pc_v2, p_out_v4b, p_out_f = (m.id() for _ in range(9))
    c_int0, c_int1, c_f0, c_f1, c_f2, c_v2_two, c_v2_one = (m.id() for _ in range(7))
    in_pos, in_uv, in_color, out_uv, out_color, pv_var, pc_var = (m.id() for _ in range(7))
    main, label = m.id(), m.id()

    m.header += [
        i("Capability", 1),                       # Shader
        i("MemoryModel", 0, 1),                   # Logical, GLSL450
        i("EntryPoint", 0, main, string_words("main"), in_pos, in_uv, in_color, out_uv, out_color, pv_var),
    ]
    m.names += [i("Name", main, string_words("main"))]
    m.annotations += [
        i("Decorate", in_pos, DECORATION["Location"], 0),
        i("Decorate", in_uv, DECORATION["Location"], 1),
        i("Decorate", in_color, DECORATION["Location"], 2),
        i("Decorate", out_uv, DECORATION["Location"], 0),
        i("Decorate", out_color, DECORATION["Location"], 1),
        i("MemberDecorate", pv_struct, 0, DECORATION["BuiltIn"], 0),   # Position
        i("MemberDecorate", pv_struct, 1, DECORATION["BuiltIn"], 1),   # PointSize
        i("Decorate", pv_struct, DECORATION["Block"]),
        i("MemberDecorate", pc_struct, 0, DECORATION["Offset"], 0),
        i("Decorate", pc_struct, DECORATION["Block"]),
    ]
    m.types += [
        i("TypeVoid", void),
        i("TypeFunction", fn, void),
        i("TypeFloat", flt, 32),
        i("TypeVector", vec2, flt, 2),
        i("TypeVector", vec4, flt, 4),
        i("TypeInt", int_, 32, 1),
        i("TypeStruct", pv_struct, vec4, flt),
        i("TypeStruct", pc_struct, vec2),
        i("TypePointer", p_in_v2, STORAGE["Input"], vec2),
        i("TypePointer", p_in_v4, STORAGE["Input"], vec4),
        i("TypePointer", p_out_v2, STORAGE["Output"], vec2),
        i("TypePointer", p_out_v4, STORAGE["Output"], vec4),
        i("TypePointer", p_out_pv, STORAGE["Output"], pv_struct),
        i("TypePointer", p_pc, STORAGE["PushConstant"], pc_struct),
        i("TypePointer", p_pc_v2, STORAGE["PushConstant"], vec2),
        i("TypePointer", p_out_f, STORAGE["Output"], flt),
        i("Constant", int_, c_int0, 0),
        i("Constant", int_, c_int1, 1),
        i("Constant", flt, c_f0, float_bits(0.0)),
        i("Constant", flt, c_f1, float_bits(1.0)),
        i("Constant", flt, c_f2, float_bits(2.0)),
        i("ConstantComposite", vec2, c_v2_two, c_f2, c_f2),
        i("ConstantComposite", vec2, c_v2_one, c_f1, c_f1),
        i("Variable", p_in_v2, in_pos, STORAGE["Input"]),
        i("Variable", p_in_v2, in_uv, STORAGE["Input"]),
        i("Variable", p_in_v4, in_color, STORAGE["Input"]),
        i("Variable", p_out_v2, out_uv, STORAGE["Output"]),
        i("Variable", p_out_v4, out_color, STORAGE["Output"]),
        i("Variable", p_out_pv, pv_var, STORAGE["Output"]),
        i("Variable", p_pc, pc_var, STORAGE["PushConstant"]),
    ]

    pos, scale_ptr, scale, scaled, doubled, shifted, x, y, position = (m.id() for _ in range(9))
    pos_ptr, size_ptr, uv, color = m.id(), m.id(), m.id(), m.id()
    m.code += [
        i("Function", void, main, 0, fn),
        i("Label", label),
        i("Load", vec2, pos, in_pos),
        i("AccessChain", p_pc_v2, scale_ptr, pc_var, c_int0),
        i("Load", vec2, scale, scale_ptr),
        i("FMul", vec2, scaled, pos, scale),
        i("FMul", vec2, doubled, scaled, c_v2_two),
        i("FSub", vec2, shifted, doubled, c_v2_one),
        i("CompositeExtract", flt, x, shifted, 0),
        i("CompositeExtract", flt, y, shifted, 1),
        i("CompositeConstruct", vec4, position, x, y, c_f0, c_f1),
        i("AccessChain", p_out_v4, pos_ptr, pv_var, c_int0),
        i("Store", pos_ptr, position),
        i("AccessChain", p_out_f, size_ptr, pv_var, c_int1),
        i("Store", size_ptr, c_f1),
        i("Load", vec2, uv, in_uv),
        i("Store", out_uv, uv),
        i("Load", vec4, color, in_color),
        i("Store", out_color, color),
        i("Return"),
        i("FunctionEnd"),
    ]
    return m.assemble()


def fragment_shader():
    """
    #version 450
    layout(set = 0, binding = 0) uniform sampler2D tex;
    layout(location = 0) in vec2 inUV;
    layout(location = 1) in vec4 inColor;
    layout(location = 0) out vec4 outColor;
    void main() {
        outColor = inColor * texture(tex, inUV);
    }
    """
    m = Module()
    i = m.inst
    void, fn, flt, vec2, vec4 = m.id(), m.id(), m.id(), m.id(), m.id()
    image, sampled, p_uc, p_in_v2, p_in_v4, p_out_v4 = (m.id() for _ in range(6))
    tex, in_uv, in_color, out_color = (m.id() for _ in range(4))
    main, label = m.id(), m.id()

    m.header += [
        i("Capability", 1),
        i("MemoryModel", 0, 1),
        i("EntryPoint", 4, main, string_words("main"), in_uv, in_color, out_color),
        i("ExecutionMode", main, 7),              # OriginUpperLeft
    ]
    m.names += [i("Name", main, string_words("main"))]
    m.annotations += [
        i("Decorate", in_uv, DECORATION["Location"], 0),
        i("Decorate", in_color, DECORATION["Location"], 1),
        i("Decorate", out_color, DECORATION["Location"], 0),
        i("Decorate", tex, DECORATION["DescriptorSet"], 0),
        i("Decorate", tex, DECORATION["Binding"], 0),
    ]
    m.types += [
        i("TypeVoid", void),
        i("TypeFunction", fn, void),
        i("TypeFloat", flt, 32),
        i("TypeVector", vec2, flt, 2),
        i("TypeVector", vec4, flt, 4),
        i("TypeImage", image, flt, 1, 0, 0, 0, 1, 0),   # 2D, not depth, not arrayed, single sampled, sampled, unknown format
        i("TypeSampledImage", sampled, image),
        i("TypePointer", p_uc, STORAGE["UniformConstant"], sampled),
        i("TypePointer", p_in_v2, STORAGE["Input"], vec2),
        i("TypePointer", p_in_v4, STORAGE["Input"], vec4),
        i("TypePointer", p_out_v4, STORAGE["Output"], vec4),
        i("Variable", p_uc, tex, STORAGE["UniformConstant"]),
        i("Variable", p_in_v2, in_uv, STORAGE["Input"]),
        i("Variable", p_in_v4, in_color, STORAGE["Input"]),
        i("Variable", p_out_v4, out_color, STORAGE["Output"]),
    ]

    uv, color, image_value, sample, result = (m.id() for _ in range(5))
    m.code += [
        i("Function", void, main, 0, fn),
        i("Label", label),
        i("Load", vec2, uv, in_uv),
        i("Load", vec4, color, in_color),
        i("Load", sampled, image_value, tex),
        i("ImageSampleImplicitLod", vec4, sample, image_value, uv),
        i("FMul", vec4, result, color, sample),
        i("Store", out_color, result),
        i("Return"),
        i("FunctionEnd"),
    ]
    return m.assemble()


def emit(name, words, out):
    out.write("static const unsigned int %s[] = {\n" % name)
    for index in range(0, len(words), 8):
        out.write("\t" + ", ".join("0x%08x" % w for w in words[index:index + 8]) + ",\n")
    out.write("};\n")


with open(sys.argv[1], "w", newline="\n") as out:
    out.write("// Generated by tools/generate_shaders.py, do not edit.\n")
    emit("bb_shader_vertex", vertex_shader(), out)
    emit("bb_shader_fragment", fragment_shader(), out)
